const char* frontend_script = "(()=>{function e(e){let[t,l]=e.querySelectorAll(\"input,select\");if(!t.reportValidity())return;let n=document.getElementById(\"meter_template\").content.firstElementChild.cloneNode(!0),r=n.querySelector('input[type=\"text\"]');n.querySelector(\"h3\").firstChild.nodeValue=t.value+\" \"+l.value,n.querySelector('input[type=\"checkbox\"]').value=t.value+\",\"+l.value,r.name=\"key_\"+t.value,document.getElementById(\"new_meter\").before(n),e.close(),r.focus()}window.addEventListener(\"DOMContentLoaded\",()=>{let t=document.getElementById(\"meter_dialog\");document.body.append(t),document.getElementById(\"new_meter\").addEventListener(\"click\",()=>t.showModal()),t.querySelector(\"button\").addEventListener(\"click\",()=>e(t))})})();";
